        {{end}}
      </div>
      {{if .Answered}}
        <div class="receipt {{if .WasCorrect}}ok{{else}}miss{{end}}">
          <div class="receipt-head pixel">{{if .WasCorrect}}CORRECT{{else}}MISS{{end}}</div>
          <div class="receipt-line">{{.Fact}}</div>
          {{with .Source}}
            <div class="receipt-src">SRC
              {{if $.Question.SourceURL}}<a href="{{$.Question.SourceURL}}" target="_blank" rel="noopener">{{.}}</a>{{else}}{{.}}{{end}}
            </div>
