@keyframes print { from { clip-path: inset(0 0 100% 0); transform: translateY(-6px); } to { transform: none; } }
.receipt-head { font-size: 11px; letter-spacing: 2px; border-bottom: 1px dashed rgba(19,52,84,.35); padding-bottom: 8px; margin-bottom: 10px; }
