.printer-head::after { right: 13px; }
.printer-slot {
  position: absolute; left: 7%; right: 7%; bottom: 4px; height: 9px;
  border-radius: 6px; background: #030405; box-shadow: inset 0 3px 4px rgba(0,0,0,.72), 0 1px 0 rgba(255,255,255,.1);
}
