		`class="printer-slot"`,
		`class="receipt-paper"`,
		"RECEIPT · Cities",
		"Lisbon was founded around 1200 BC.",
		"every line above has a source",
	} {
		if !strings.Contains(html, want) {
			t.Errorf("rendered results are missing %q", want)
		}
	}
}

