/* The final fact summary feeds out of a receipt printer. The paper and its
 * contents keep the established receipt treatment; only the entrance gains
 * physical depth and a stepped thermal-printer rhythm. */
.receipt-printer { position: relative; margin-top: 26px; padding: 0 10px 18px; perspective: 900px; }
.printer-head {
  position: relative; z-index: 4; height: 34px; margin: 0 -10px;
  border: 2px solid var(--line); border-radius: 10px 10px 5px 5px;
  background: linear-gradient(180deg, #242830 0%, #171A20 58%, #0E1014 100%);
