  border-radius: 2px; background: #08090B; box-shadow: inset 1px 1px 0 rgba(255,255,255,.1);
}
.printer-head::before { left: 13px; }
.printer-head::after { right: 13px; }
.printer-slot {
  position: absolute; left: 7%; right: 7%; bottom: 4px; height: 9px;
  border-radius: 6px; background: #030405; box-shadow: inset 0 3px 4px rgba(0,0,0,.72), 0 1px 0 rgba(255,255,255,.1);
}
.printer-light {
  position: absolute; z-index: 2; right: 28px; top: 7px; width: 5px; height: 5px;
  border-radius: 50%; background: var(--accent); box-shadow: 0 0 7px var(--accent);
  animation: printer-blink .18s steps(2, end) 12;
}
.receipt-stage { position: relative; margin: -2px 10px 0; filter: drop-shadow(7px 12px 10px rgba(0,0,0,.38)); }
.receipt-paper {
  position: relative; z-index: 2; transform-origin: top center;
  clip-path: inset(0 0 100% 0); animation: receipt-feed 2.2s steps(22, end) .18s both, receipt-settle .55s ease-out 2.45s both;
}
.receipt-curl {
  position: absolute; z-index: 3; left: 1px; right: 1px; top: -1px; height: 18px;
  border-radius: 0 0 48% 48%;
  background: linear-gradient(180deg, rgba(255,255,255,.96) 0%, #d7d2c8 42%, var(--paper) 76%, rgba(25,28,34,.16) 100%);
  box-shadow: 0 5px 7px rgba(0,0,0,.22);
  animation: receipt-edge 2.2s steps(22, end) .18s both, curl-away .22s ease-out 2.42s forwards;
}
@keyframes printer-blink { 0%, 100% { opacity: .25; } 50% { opacity: 1; } }
@keyframes receipt-feed {
  0% { clip-path: inset(0 0 100% 0); }
  100% { clip-path: inset(0 0 0 0); }
}
@keyframes receipt-edge {
