}
@keyframes curl-away { to { opacity: 0; transform: rotateX(-65deg) translateY(5px); } }
@keyframes receipt-settle {
  0% { transform: rotateX(-2.5deg) translateY(-2px); }
  65% { transform: rotateX(1deg) translateY(1px); }
