.confetti i:nth-child(3) { left: 22%; animation-delay: .1s } .confetti i:nth-child(4) { left: 31%; animation-delay: .5s }
.confetti i:nth-child(5) { left: 40%; animation-delay: .2s } .confetti i:nth-child(6) { left: 49%; animation-delay: .6s }
