.home-play {
  min-width: 178px; padding: 17px 20px 17px 26px;
  display: inline-flex; justify-content: space-between; align-items: center; gap: 38px;
  background: var(--accent); color: var(--accent-ink); border: 1px solid var(--accent); border-radius: 999px;
  box-shadow: 0 12px 45px rgba(114,241,198,.15); font-size: 15px;
}
.home-play:hover:not(:disabled) { background: #9AF6D7; border-color: #9AF6D7; }
.home-play i { font-style: normal; font-size: 21px; font-weight: 400; line-height: 1; }
.home-meta {
  margin: 24px 0 0; color: #6F7783; font-size: 10px;
  letter-spacing: .12em; text-transform: uppercase;
}
.home-art { min-height: min(64vh, 650px); position: relative; display: grid; place-items: center; }
.home-art img {
  width: min(52vw, 650px); height: auto; position: relative; z-index: 2;
  filter: grayscale(1) contrast(1.12) drop-shadow(0 42px 42px rgba(0,0,0,.7));
  animation: die-float 7s ease-in-out infinite;
}
.die-orbit {
  position: absolute; width: min(42vw, 520px); aspect-ratio: 1; border: 1px solid rgba(255,255,255,.32);
  border-radius: 50%; transform: rotateX(70deg) rotateZ(-14deg); box-shadow: inset 0 0 60px rgba(255,255,255,.03);
}
.die-note {
  position: absolute; z-index: 3; color: #888; font-size: 9px; letter-spacing: .28em;
  writing-mode: vertical-rl;
}
.note-top { right: 2%; top: 12%; }
.note-bottom { left: 2%; bottom: 12%; transform: rotate(180deg); }
@keyframes die-float {
  0%, 100% { transform: translateY(0) rotate(-1.5deg); }
  50% { transform: translateY(-15px) rotate(1.5deg); }
}
.home-foot {
  position: relative; left: auto; right: auto; bottom: auto; z-index: 2;
  display: flex; justify-content: space-between; gap: 18px; margin: 0;
  color: #616975; font-size: 9px; letter-spacing: .17em;
}
.lobby-setting { display: grid; grid-template-columns: 84px 1fr; align-items: center; gap: 12px; }
.seg.questions span { width: 54px; }

@media (max-width: 760px) {
  .home-shell { min-height: 100svh; padding: 22px 20px 18px; }
  .hero-big { grid-template-columns: 1fr; gap: 10px; padding: 6vh 0 3vh; text-align: center; }
  .home-copy { display: flex; flex-direction: column; align-items: center; }
  .home-shell .wordmark { font-size: clamp(46px, 14vw, 82px); }
  .home-shell .hero-line { max-width: 32ch; margin-top: 22px; }
  .home-shell .play-strip { justify-content: center; margin-top: 26px; }
  .home-art { min-height: 30vh; order: -1; margin-bottom: -3vh; }
  .home-art img { width: min(76vw, 380px); }
  .die-orbit { width: min(64vw, 320px); }
  .die-note { display: none; }
  .home-foot { font-size: 8px; letter-spacing: .08em; }
}
@media (prefers-reduced-motion: reduce) { .home-art img { animation: none; } }

/* ---- shared dark composition ------------------------------------------ */
::selection { background: rgba(114,241,198,.28); color: var(--ink); }
.hero-title em { color: var(--accent); background: transparent; padding: 0; outline: 0; }
.hero-title, .prompt, h2.h2 { text-wrap: balance; }
.topbar { align-items: center; padding: 4px 0 18px; border-bottom: 1px solid rgba(255,255,255,.055); }
.column { width: 100%; }
.card::before {
  content: ''; position: absolute; inset: 0; pointer-events: none; border-radius: inherit;
  background: linear-gradient(145deg, rgba(255,255,255,.025), transparent 36%);
}
.ghost { background: transparent; border-color: var(--line); }
}

func TestHomeHasOnlyPlayAction(t *testing.T) {
	var out bytes.Buffer
	v := homeView{Letters: strings.Split("DEEZ.WIN", "")}
	if err := homeTmpl.ExecuteTemplate(&out, "layout", v); err != nil {
		t.Fatal(err)
	}
	html := out.String()
	if got := strings.Count(html, "<button"); got != 1 {
		t.Fatalf("home has %d buttons, want only Play", got)
	}
	if !strings.Contains(html, `action="/play"`) || !strings.Contains(html, ">Play</span>") {
		t.Fatal("home Play action does not lead to the lobby page")
	}
	if !strings.Contains(html, `/dice-d6.png`) || !strings.Contains(html, "6 SIDES") || strings.Contains(html, "d12") {
		t.Fatal("home does not use the six-sided die identity")
	}
}

func TestSixSidedDiceAssets(t *testing.T) {
	for path, wantSize := range map[string]int{
		"static/favicon.png": 128,
		"static/dice-d6.png": 720,
	} {
		f, err := staticFS.Open(path)
		if err != nil {
			t.Fatal(err)
		}
		config, _, err := image.DecodeConfig(f)
		f.Close()
		if err != nil {
			t.Fatalf("decode %s: %v", path, err)
		}
		if config.Width != wantSize || config.Height != wantSize {
			t.Errorf("%s is %dx%d, want %dx%d", path, config.Width, config.Height, wantSize, wantSize)
		}
	}
}

func TestSharedDarkThemeIncludesMobileLayout(t *testing.T) {
	css, err := staticFS.ReadFile("static/app.css")
	if err != nil {
		t.Fatal(err)
	}
	styles := string(css)
	for _, want := range []string{
		"--bg: #07080A",
		"--panel: #101216",
		"--accent: #72F1C6",
		"@media (max-width: 560px)",
		"min-height: 44px",
	} {
		if !strings.Contains(styles, want) {
			t.Errorf("shared theme is missing %q", want)
		}
	}
}

